/* Iron League — short pit cues from the shared sound pack. */
(function (root) {
  const IL = root.IL = root.IL || {};
  const CLIPS = {"click":"data:audio/mpeg;base64,","hit":"data:audio/mpeg;base64,","crit":"data:audio/mpeg;base64,","ko":"data:audio/mpeg;base64,","magic":"data:audio/mpeg;base64,","victory":"data:audio/mpeg;base64,","defeat":"data:audio/mpeg;base64,"};
  let lastKind = "";
  let lastAt = 0;
  function play(kind, volume) {
    const src = CLIPS[kind];
    const vol = Number(volume);
    if (!src || !(vol > 0) || typeof Audio === "undefined") return;
    const now = (typeof performance !== "undefined" && performance.now) ? performance.now() : Date.now();
    if (kind === lastKind && now - lastAt < 90) return;
    if (kind === "hit" && lastKind === "crit" && now - lastAt < 120) return;
    lastKind = kind;
    lastAt = now;
    try {
      const audio = new Audio(src);
      audio.volume = Math.max(0, Math.min(1, vol));
      const pending = audio.play();
      if (pending && typeof pending.then === "function") pending.then(function () {}, function () {});
    } catch (err) { /* a blocked cue never stops the pit */ }
  }
  IL.sfx = { play: play, clips: Object.keys(CLIPS) };
})(typeof window !== "undefined" ? window : globalThis);
